arguments.cmd:
cd /app && cat > output/assets/styles.css <<'CSS'
:root {
  /* Palette (OKLCH per skill) */
  --brand-primary: oklch(56% 0.22 265); /* ~#3861FB */
  --brand-primary-2: oklch(62% 0.18 265);
  --text: oklch(18% 0.03 260);         /* deep navy */
  --text-2: oklch(42% 0.03 260);
  --muted: oklch(55% 0.02 260);
  --bg: oklch(98% 0.01 255);
  --bg-2: oklch(96% 0.01 255);
  --surface: oklch(100% 0 0);
  --border: oklch(89% 0.015 255);

  --pos: oklch(64% 0.19 150); /* close to #16c784 */
  --neg: oklch(58% 0.22 25);  /* close to #ea3943 */
  --warn: oklch(76% 0.14 85);

  --shadow: 0 10px 30px oklch(20% 0.03 260 / 0.08);
  --shadow-soft: 0 8px 20px oklch(20% 0.03 260 / 0.06);

  --radius-1: 10px;
  --radius-2: 14px;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;

  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.25;
}

a { color: inherit; text-decoration: none; }

.skip {
  position: absolute;
  left: -999px;
  top: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  padding: 10px 12px;
  border-radius: 10px;
  z-index: 1000;
}
.skip:focus { left: 12px; }

:focus-visible {
  outline: 2px solid var(--brand-primary);
  outline-offset: 2px;
}

.container {
  width: min(1440px, 100%);
  margin: 0 auto;
  padding: 20px 20px 56px;
}

.shell-header {
  background: linear-gradient(180deg, var(--surface), var(--bg));
  border-bottom: 1px solid var(--border);
}

.topbar {
  display: grid;
  grid-template-columns: 260px 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 16px 20px;
}

.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  background: radial-gradient(circle at 30% 30%, var(--brand-primary-2), var(--brand-primary));
  box-shadow: 0 8px 18px oklch(56% 0.22 265 / 0.25);
}
.brand-name { font-weight: 700; letter-spacing: -0.02em; }
.brand-name span { color: var(--brand-primary); }

.nav {
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
}
.nav-link {
  padding: 8px 10px;
  border-radius: 10px;
  color: var(--text-2);
  font-weight: 600;
  font-size: 13px;
}
.nav-link:hover { background: var(--bg-2); color: var(--text); }
.nav-link.is-active { color: var(--text); background: var(--bg-2); }

.topbar-actions { display: flex; gap: 10px; }

.btn {
  border: 1px solid transparent;
  background: var(--surface);
  color: var(--text);
  padding: 10px 12px;
  border-radius: 12px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
}
.btn:hover { transform: translateY(-1px); box-shadow: var(--shadow-soft); }
.btn:active { transform: translateY(0); box-shadow: none; }
.btn-ghost { border-color: var(--border); background: var(--surface); }
.btn-primary { background: var(--brand-primary); color: oklch(98% 0.01 255); border-color: oklch(56% 0.22 265 / 0.3); }

.market-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(160px, 1fr)) auto;
  gap: 10px;
  align-items: stretch;
  padding: 10px 20px 16px;
}

.stat {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-2);
  padding: 12px 12px;
  box-shadow: 0 1px 0 oklch(100% 0 0 / 1);
}
.stat-label { font-size: 12px; color: var(--muted); font-weight: 600; }
.stat-value { font-size: 18px; font-weight: 800; letter-spacing: -0.02em; margin-top: 4px; }
.stat-sub { font-size: 12px; margin-top: 6px; font-weight: 700; }

.stats-right {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: flex-end;
}
.mini {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 12px 12px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-2);
  min-width: 170px;
}
.mini-label { font-size: 12px; color: var(--muted); font-weight: 700; }
.mini-value { font-size: 14px; font-weight: 800; }

.promo {
  margin: 0 20px 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--shadow-soft);
  display: grid;
  grid-template-columns: 42px 1fr 42px;
  align-items: center;
  overflow: hidden;
  position: relative;
}
.promo-arrow {
  height: 100%;
  border: 0;
  background: transparent;
  font-size: 24px;
  color: var(--muted);
  cursor: pointer;
}
.promo-arrow:hover { background: var(--bg-2); color: var(--text); }

.promo-track { position: relative; min-height: 66px; }
.promo-slide {
  display: none;
  gap: 10px;
  padding: 14px 14px;
  align-items: baseline;
}
.promo-slide.is-active { display: grid; grid-template-columns: 110px 1fr; }
.promo-pill {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--brand-primary);
}
.promo-text { font-weight: 700; font-size: 13px; }
.promo-meta { grid-column: 2; color: var(--muted); font-size: 12px; margin-top: 2px; }

.promo-dots {
  position: absolute;
  right: 14px;
  bottom: 10px;
  display: flex;
  gap: 6px;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-2);
  cursor: pointer;
}
.dot.is-active { background: var(--brand-primary); border-color: oklch(56% 0.22 265 / 0.5); }

.ai {
  margin: 0 20px 18px;
  padding: 12px 12px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: linear-gradient(180deg, var(--surface), var(--bg-2));
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 12px;
  align-items: start;
}
.ai-left { display: grid; gap: 6px; }
.ai-badge {
  width: fit-content;
  font-size: 11px;
  font-weight: 900;
  color: oklch(98% 0.01 255);
  background: var(--text);
  border-radius: 999px;
  padding: 6px 10px;
}
.ai-prompt { font-weight: 700; font-size: 13px; color: var(--text); }
.ai-asks { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-2);
  padding: 8px 10px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 12px;
  cursor: pointer;
}
.chip:hover { border-color: oklch(56% 0.22 265 / 0.4); color: var(--text); }

.filters { margin-top: 8px; }
.tabs-row { display: grid; gap: 10px; }
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.tab {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-2);
  padding: 10px 12px;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  cursor: pointer;
}
.tab:hover { border-color: oklch(56% 0.22 265 / 0.35); color: var(--text); }
.tab.is-active { background: oklch(97% 0.03 265); border-color: oklch(56% 0.22 265 / 0.25); color: var(--text); }
.tab-small { font-size: 12px; padding: 8px 10px; }

.panel {
  margin-top: 14px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 18px;
  box-shadow: var(--shadow);
}
.panel-head {
  padding: 16px 16px 10px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: start;
  gap: 12px;
}
.panel-title h1 { margin: 0; font-size: 18px; letter-spacing: -0.02em; }
.panel-sub { color: var(--muted); font-size: 13px; margin-top: 6px; }

.panel-actions { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.select {
  border: 1px solid var(--border);
  background: var(--bg-2);
  padding: 10px 12px;
  border-radius: 12px;
  font-weight: 800;
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: default;
  user-select: none;
}
.select .chev { color: var(--muted); font-weight: 900; }

.panel-inline { padding: 0 16px 12px; }
.index-row {
  border: 1px solid var(--border);
  background: linear-gradient(180deg, var(--bg-2), var(--surface));
  border-radius: 14px;
  padding: 12px 12px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
}
.idx-label { font-weight: 800; font-size: 13px; }
.idx-metrics { display: flex; gap: 12px; align-items: baseline; }
.idx-price { font-weight: 900; }

.panel-body {
  position: relative;
  padding: 0 16px 16px;
}

.popover {
  display: none;
  position: absolute;
  right: 16px;
  top: 8px;
  width: min(420px, calc(100% - 32px));
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 12px;
  z-index: 20;
}
.popover.is-open { display: block; }
.popover-title { font-weight: 900; font-size: 13px; margin-bottom: 10px; }
.popover-foot { margin-top: 10px; display: flex; gap: 10px; align-items: center; color: var(--muted); font-size: 12px; justify-content: space-between; }
.kbd {
  font-family: var(--mono);
  border: 1px solid var(--border);
  background: var(--bg-2);
  padding: 2px 6px;
  border-radius: 8px;
  font-size: 12px;
}

.popover-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.field { display: grid; gap: 6px; }
.field-label { font-size: 12px; font-weight: 800; color: var(--muted); }
.input {
  width: 100%;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  font-weight: 700;
  font-size: 13px;
  color: var(--text);
}
.filter-grid { display: grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 10px; }

.table-wrap {
  margin-top: 12px;
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: auto;
  background: var(--surface);
}

.table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  min-width: 1080px;
}

.table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: linear-gradient(180deg, var(--surface), var(--bg-2));
  border-bottom: 1px solid var(--border);
  padding: 12px 10px;
  font-size: 12px;
  color: var(--muted);
  text-align: left;
  white-space: nowrap;
}

.table thead th.sortable { cursor: pointer; }
.table thead th.sortable:hover { color: var(--text); }

.table tbody td {
  border-bottom: 1px solid oklch(92% 0.01 255);
  padding: 12px 10px;
  font-size: 13px;
  white-space: nowrap;
  vertical-align: middle;
}

.table tbody tr:hover { background: oklch(98% 0.01 255); }

.col-rank { width: 60px; }
.col-name { width: 320px; }
.col-spark { width: 140px; }

.num { text-align: right; }

.name-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.coin-dot {
  width: 26px;
  height: 26px;
  border-radius: 9px;
  background: radial-gradient(circle at 30% 30%, oklch(85% 0.12 265), oklch(62% 0.18 265));
  border: 1px solid oklch(56% 0.22 265 / 0.2);
}

.coin-meta { display: grid; gap: 2px; }
.coin-name { font-weight: 800; }
.coin-sym { font-size: 12px; color: var(--muted); font-weight: 800; }

.badge {
  margin-left: 8px;
  font-size: 11px;
  font-weight: 900;
  padding: 4px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-2);
  color: var(--text-2);
}

.mono { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1; font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif; }
.mono-num { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1; font-family: var(--mono); }

.positive { color: var(--pos); }
.negative { color: var(--neg); }
.neutral { color: var(--text-2); }
.muted { color: var(--muted); }

.spark {
  width: 120px;
  height: 28px;
}

.table-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 2px 0;
  gap: 12px;
  flex-wrap: wrap;
}
.foot-left { color: var(--muted); font-size: 13px; font-weight: 700; }

.pager { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.page {
  border: 1px solid var(--border);
  background: var(--surface);
  padding: 8px 10px;
  border-radius: 12px;
  font-weight: 900;
  font-size: 12px;
  cursor: pointer;
}
.page:hover { border-color: oklch(56% 0.22 265 / 0.35); }
.page.is-active { background: oklch(97% 0.03 265); border-color: oklch(56% 0.22 265 / 0.25); }
.page.is-ellipsis { cursor: default; background: var(--bg-2); color: var(--muted); }

.summary {
  margin-top: 18px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 18px;
  padding: 16px 16px;
}
.summary-head { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; }
.summary h2 { margin: 0; font-size: 16px; letter-spacing: -0.01em; }
.summary-text { margin: 12px 0 0; color: var(--text-2); font-size: 14px; line-height: 1.5; }

.link {
  border: 0;
  background: transparent;
  color: var(--brand-primary);
  font-weight: 900;
  cursor: pointer;
  font-size: 13px;
}
.link:hover { text-decoration: underline; }

.content {
  margin-top: 18px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 18px;
  padding: 16px 16px;
}
.content h2 { margin: 0 0 10px; font-size: 16px; }
.content h3 { margin: 16px 0 8px; font-size: 14px; }
.content p { margin: 0; color: var(--text-2); line-height: 1.6; }

.footer {
  margin-top: 18px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 18px;
  padding: 18px 16px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}
.footer-col a { display: block; color: var(--text-2); padding: 6px 0; font-weight: 700; font-size: 13px; }
.footer-col a:hover { color: var(--text); }
.footer-title { font-weight: 900; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }
.footer-bottom { margin-top: 14px; border-top: 1px solid var(--border); padding-top: 12px; color: var(--muted); font-size: 13px; font-weight: 700; }

@media (max-width: 980px) {
  .topbar { grid-template-columns: 1fr auto; grid-template-areas: "brand actions" "nav nav"; }
  .brand { grid-area: brand; }
  .topbar-actions { grid-area: actions; }
  .nav { grid-area: nav; }

  .market-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stats-right { grid-column: 1 / -1; justify-content: flex-start; }

  .ai { grid-template-columns: 1fr; }
  .filter-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .btn:hover { transform: none; }
}
CSS

