from html.parser import HTMLParser

class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=set(); self.dataattrs=set(); self.actions=set()
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a: self.ids.add(a['id'])
        for k in a:
            if k.startswith('data-'): self.dataattrs.add(k)
        if 'data-action' in a: self.actions.add(a['data-action'])

html=open('/app/output/index.html','r',encoding='utf8').read()
p=P(); p.feed(html)
print('rankingsTable' in p.ids)
print('pager' in p.ids)
print('toggleColumns' in p.actions, 'toggleFilters' in p.actions)
